/* AgentKontor Widget v3.1 min | DSGVO-konform | (c) superhecht.ai */
(function(){const I=window.AK_AGENT_ID;if(!I)return;const B=(()=>{const s=document.currentScript;return s&&s.src?s.src.replace(/\/widget\.min\.js.*/,''):'https://agentkontor.de'})();const PK='ak_prv_'+I,SK='ak_sid_'+I;let sid=localStorage.getItem(SK);if(!sid){sid='w_'+Math.random().toString(36).slice(2)+Date.now().toString(36);localStorage.setItem(SK,sid);}async function init(){let cfg;try{const r=await fetch(B+'/api/chat/widget-config/'+I);if(!r.ok)return;cfg=await r.json();}catch{return;}if(!cfg||!cfg.widget_enabled)return;const pos=cfg.widget_position||'right',delay=parseInt(cfg.widget_delay)||0,theme=cfg.widget_theme||'dark',size=parseInt(cfg.widget_size)||56,color=cfg.color||'#6c5ce7',emoji=cfg.emoji||'💬',name=cfg.name||'Agent',greeting=cfg.greeting||'Hallo!';const lgt=theme==='light';const bg=lgt?'#fff':'#0c0c1e',bgm=lgt?'#f4f4f8':'#1e1e38',tx=lgt?'#1a1a2e':'#e0e0f0',mu=lgt?'#888':'#8888aa',bd=lgt?'rgba(0,0,0,.1)':'rgba(255,255,255,.08)',ib=lgt?'#f4f4f8':'rgba(255,255,255,.06)';const hs=pos==='left'?'left:20px':'right:20px';const st=document.createElement('style');st.textContent=`#ak-btn{position:fixed;bottom:20px;${hs};width:${size}px;height:${size}px;border-radius:50%;background:${color};border:none;cursor:pointer;box-shadow:0 4px 20px rgba(0,0,0,.3);z-index:2147483646;font-size:${Math.round(size*.42)}px;display:flex;align-items:center;justify-content:center;transition:transform .2s}#ak-btn:hover{transform:scale(1.08)}#ak-frame{position:fixed;bottom:${size+30}px;${hs};width:360px;height:520px;max-height:calc(100vh - 120px);background:${bg};border:1px solid ${bd};border-radius:16px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.35);z-index:2147483645;display:none;flex-direction:column;opacity:0;transform:translateY(12px) scale(.97);transition:opacity .2s,transform .2s}#ak-frame.open{opacity:1;transform:none}.ak-h{padding:11px 14px;display:flex;align-items:center;gap:10px;border-bottom:1px solid ${bd}}.ak-ha{width:32px;height:32px;border-radius:50%;background:${color}33;display:flex;align-items:center;justify-content:center}.ak-hx{margin-left:auto;background:none;border:none;cursor:pointer;color:${mu};font-size:1.1rem;padding:2px 6px}.ak-msgs{flex:1;overflow-y:auto;padding:11px;display:flex;flex-direction:column;gap:8px;scroll-behavior:smooth}.ak-b{max-width:83%;padding:8px 12px;border-radius:12px;font-size:.82rem;line-height:1.55;word-break:break-word}.ak-b.bot{background:${bgm};color:${tx};border-bottom-left-radius:2px;align-self:flex-start}.ak-b.usr{background:${color};color:#fff;border-bottom-right-radius:2px;align-self:flex-end}.ak-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:${mu};animation:akB .9s infinite;margin:0 2px}.ak-dot:nth-child(2){animation-delay:.15s}.ak-dot:nth-child(3){animation-delay:.3s}@keyframes akB{0%,60%,100%{transform:none}30%{transform:translateY(-5px)}}.ak-chips{display:flex;flex-wrap:wrap;gap:4px;padding:0 11px 7px}.ak-chip{background:${ib};border:1px solid ${bd};border-radius:20px;padding:3px 10px;font-size:.73rem;color:${tx};cursor:pointer}.ak-foot{padding:9px 11px;border-top:1px solid ${bd};display:flex;gap:6px}.ak-inp{flex:1;background:${ib};border:1px solid ${bd};border-radius:8px;padding:7px 11px;color:${tx};font-size:.82rem;outline:none;resize:none;font-family:inherit}.ak-inp:focus{border-color:${color}}.ak-send{width:34px;height:34px;border-radius:8px;background:${color};border:none;cursor:pointer;color:#fff;font-size:.9rem;display:flex;align-items:center;justify-content:center}.ak-prv{position:absolute;inset:0;background:${bg};z-index:10;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;text-align:center}.ak-pw{text-align:center;font-size:.62rem;color:${mu};padding:3px 0 5px}@media(max-width:420px){#ak-frame{width:calc(100vw - 20px)}}`;
document.head.appendChild(st);const btn=document.createElement('button');btn.id='ak-btn';btn.innerHTML=emoji;document.body.appendChild(btn);const frame=document.createElement('div');frame.id='ak-frame';frame.innerHTML=`<div class="ak-h" style="background:${color}18"><div class="ak-ha">${emoji}</div><div><div style="font-size:.86rem;font-weight:700;color:${tx}">${name}</div><div style="font-size:.68rem;color:#00b894">● Online</div></div><button class="ak-hx">✕</button></div><div class="ak-msgs" id="ak-m"></div><div class="ak-chips" id="ak-c"></div><div class="ak-foot"><textarea class="ak-inp" id="ak-i" placeholder="Nachricht…" rows="1"></textarea><button class="ak-send" id="ak-s">➤</button></div><div class="ak-pw">Powered by <a href="https://agentkontor.de" target="_blank" style="color:${mu}">AgentKontor</a></div>`;document.body.appendChild(frame);
let open=false,sessionId=null,hist=[],privOk=localStorage.getItem(PK)==='1';
const m=document.getElementById('ak-m'),inp=document.getElementById('ak-i'),snd=document.getElementById('ak-s'),chips=document.getElementById('ak-c');

function showPrivacy(onOk){const d=document.createElement('div');d.className='ak-prv';d.innerHTML=`<div style="font-size:1.5rem;margin-bottom:10px">🔒</div><div style="font-size:.9rem;font-weight:700;color:${tx};margin-bottom:8px">Datenschutzhinweis</div><p style="font-size:.75rem;color:${mu};line-height:1.6;margin-bottom:18px">Nachrichten werden zur KI-Verarbeitung an Anthropic (USA) übermittelt und für max. ${cfg.data_retention_days||90} Tage gespeichert.</p><button id="ak-ok" style="width:100%;padding:9px;background:${color};color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:.82rem;font-weight:600;margin-bottom:7px">Verstanden &amp; fortfahren</button><button id="ak-fgt" style="width:100%;padding:7px;background:transparent;border:1px solid ${bd};border-radius:8px;cursor:pointer;font-size:.75rem;color:${mu}">Meine Daten löschen</button>`;frame.appendChild(d);document.getElementById('ak-ok').onclick=()=>{localStorage.setItem(PK,'1');privOk=true;d.remove();onOk();};document.getElementById('ak-fgt').onclick=async()=>{try{await fetch(B+'/api/widget/forget',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({agentId:I,sessionIdentifier:sid})});}catch{}localStorage.removeItem(PK);localStorage.removeItem(SK);d.innerHTML=`<div style="color:${mu};font-size:.82rem">✓ Daten werden gelöscht.</div>`;setTimeout(()=>d.remove(),2000);};}

function tog(f){open=f!==undefined?f:!open;if(open){frame.style.display='flex';requestAnimationFrame(()=>frame.classList.add('open'));btn.innerHTML='✕';if(!privOk){showPrivacy(()=>{if(!m.children.length)addBot(greeting,cfg.quick_chips||[]);});return;}if(!m.children.length)addBot(greeting,cfg.quick_chips||[]);inp.focus();}else{frame.classList.remove('open');setTimeout(()=>frame.style.display='none',200);btn.innerHTML=emoji;}}
function addBot(t,qc=[]){const d=document.createElement('div');d.className='ak-b bot';d.textContent=t;m.appendChild(d);chips.innerHTML='';(qc||[]).forEach(c=>{const b=document.createElement('button');b.className='ak-chip';b.textContent=c;b.onclick=()=>{inp.value=c;send();};chips.appendChild(b);});m.scrollTop=m.scrollHeight;}
function addUsr(t){chips.innerHTML='';const d=document.createElement('div');d.className='ak-b usr';d.textContent=t;m.appendChild(d);m.scrollTop=m.scrollHeight;}
function showTyping(){const d=document.createElement('div');d.className='ak-b bot';d.id='ak-ty';d.innerHTML='<span class="ak-dot"></span><span class="ak-dot"></span><span class="ak-dot"></span>';m.appendChild(d);m.scrollTop=m.scrollHeight;return d;}
async function send(){const t=inp.value.trim();if(!t)return;inp.value='';inp.style.height='auto';addUsr(t);hist.push({role:'user',content:t});snd.disabled=true;const ty=showTyping();try{const r=await fetch(B+'/api/chat/stream/'+I,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:hist,sessionId,source:'widget',sessionIdentifier:sid})});if(!r.ok||!r.headers.get('content-type')?.includes('text/event-stream')){const d=await r.json();ty.remove();const rp=d.reply||d.error||'Fehler';sessionId=d.sessionId||sessionId;hist.push({role:'assistant',content:rp});addBot(rp);snd.disabled=false;return;}ty.remove();const el=document.createElement('div');el.className='ak-b bot';m.appendChild(el);m.scrollTop=m.scrollHeight;const rd=r.body.getReader(),dec=new TextDecoder();let ft='',buf='';while(1){const{done,value}=await rd.read();if(done)break;buf+=dec.decode(value,{stream:true});const ls=buf.split('\n');buf=ls.pop()||'';for(const l of ls){if(!l.startsWith('data: '))continue;try{const ev=JSON.parse(l.slice(6));if(ev.type==='session')sessionId=ev.sessionId;if(ev.type==='text'){ft+=ev.text;el.textContent=ft;m.scrollTop=m.scrollHeight;}}catch{}}}hist.push({role:'assistant',content:ft});}catch{if(ty.parentNode)ty.remove();addBot('Verbindungsfehler.');}snd.disabled=false;}
btn.addEventListener('click',()=>tog());frame.querySelector('.ak-hx').addEventListener('click',()=>tog(false));snd.addEventListener('click',send);inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}});inp.addEventListener('input',()=>{inp.style.height='auto';inp.style.height=Math.min(inp.scrollHeight,100)+'px';});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&open)tog(false);});if(delay>0)setTimeout(()=>{if(!open)tog(true);},delay*1000);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
